import { test } from 'node:test';
import assert from 'node:assert/strict';
import { aplicarMigracoes, reverterMigracoes } from './solution.mjs';

const migracoes = [
  {
    versao: 1,
    aplicar: (b) => ({ ...b, pacientes: [] }),
    reverter: (b) => {
      const { pacientes, ...resto } = b;
      return resto;
    },
  },
  {
    versao: 2,
    aplicar: (b) => ({ ...b, telefone: 'coluna adicionada' }),
    reverter: (b) => {
      const { telefone, ...resto } = b;
      return resto;
    },
  },
];

const bancoInicial = () => ({ versao: 0, nome: 'clinica' });

test('aplicarMigracoes sobe até o alvo e atualiza a versão', () => {
  const resultado = aplicarMigracoes(bancoInicial(), migracoes, 2);
  assert.deepEqual(resultado, {
    versao: 2,
    nome: 'clinica',
    pacientes: [],
    telefone: 'coluna adicionada',
  });
});

test('aplicarMigracoes com alvo menor aplica só até o alvo', () => {
  const resultado = aplicarMigracoes(bancoInicial(), migracoes, 1);
  assert.equal(resultado.versao, 1);
  assert.ok(Array.isArray(resultado.pacientes));
  assert.equal(resultado.telefone, undefined);
});

test('não reaplica o que já foi aplicado (banco na versão 1 continua igual)', () => {
  const banco = { versao: 1, nome: 'clinica', pacientes: [{ id: 1, nome: 'Ana' }] };
  const resultado = aplicarMigracoes(banco, migracoes, 2);
  assert.deepEqual(resultado.pacientes, [{ id: 1, nome: 'Ana' }]);
  assert.equal(resultado.versao, 2);
});

test('reverterMigracoes desfaz na ordem inversa, até o alvo', () => {
  const banco = aplicarMigracoes(bancoInicial(), migracoes, 2);
  // desfaz tudo: volta para a versão 0, sem pacientes e sem telefone
  const zerado = reverterMigracoes(banco, migracoes, 0);
  assert.deepEqual(zerado, { versao: 0, nome: 'clinica' });
  // desfaz só a última: volta para a versão 1, mantendo pacientes
  const meioCaminho = reverterMigracoes(banco, migracoes, 1);
  assert.equal(meioCaminho.versao, 1);
  assert.ok(Array.isArray(meioCaminho.pacientes));
  assert.equal(meioCaminho.telefone, undefined);
});

solutionCode:
// Runner de migrações simulado: sobe as versões em ordem, aplicando só
// o que falta (versao > atual e <= alvo). Cada aplicar devolve banco novo.
export function aplicarMigracoes(banco, migracoes, alvo) {
  let atual = banco;
  const emOrdem = [...migracoes].sort((a, b) => a.versao - b.versao);
  for (const migracao of emOrdem) {
    if (migracao.versao > banco.versao && migracao.versao <= alvo) {
      atual = migracao.aplicar(atual);
    }
  }
  return { ...atual, versao: alvo };
}

// Reverter: desce do mais novo para o mais antigo (pilha), desfazendo
// com reverter tudo o que está acima do alvo.
export function reverterMigracoes(banco, migracoes, alvo) {
  let atual = banco;
  const emOrdem = [...migracoes].sort((a, b) => b.versao - a.versao);
  for (const migracao of emOrdem) {
    if (migracao.versao <= banco.versao && migracao.versao > alvo) {
      atual = migracao.reverter(atual);
    }
  }
  return { ...atual, versao: alvo };
}
